\begin{document}
\maketitle

\begin{abstract}
For a semiprime $N = pq$ and a base $b$ coprime to $N$, the \emph{cycle-index fingerprint} is the freely computable sequence $F(c) = \gcd(b^{c}-1, N)$. We give a complete and exact analysis of this object and of three natural structures built on top of it: its M\"obius spectrum, its Burnside orbit average, and its information content about the secret statistic $p+q$. We prove: (i) a structure theorem, $F(c) = p^{\iv{d_p \mid c}} q^{\iv{d_q \mid c}}$ where $d_p, d_q$ are the multiplicative orders of $b$ modulo $p$ and $q$; (ii) an order seal, namely that $d^{*} = \min(d_p, d_q)$ is the least index at which $F$ is nontrivial and that $F(d^{*})$ is a proper nontrivial divisor of $N$ whenever $d_p \ne d_q$; (iii) an exact four-atom M\"obius spectrum $M_d = \iv{d=1} + (p-1)\iv{d_p=d} + (q-1)\iv{d_q=d} + \varphi(N)\iv{n=d}$ with $n = \lcmop(d_p,d_q)$, together with the delta-function identity $\sum_{c \mid d}\mu(d/c) v_p(F(c)) = \iv{d_p = d}$; (iv) a starvation theorem: on any finite instance family whose local orders exceed the observation window $D$, the truncated fingerprint carries exactly zero information, in an exact finitary counting sense, about $(p+q) \bmod \ell$ for every modulus $\ell$, and the same holds for every post-processing of the window; (v) a Burnside orbit-count identity $C\cdot n = n + (p-1)(n/d_p) + (q-1)(n/d_q) + \varphi(N)$ derived from the fact that $F(k)$ is the number of fixed points of multiplication by $b^{k}$ on $\mathbb{Z}/N$, with a dichotomy showing the orbit count is either a factoring oracle or a function of $(N, \ord_N b)$ alone; and (vi) an exponent-invariance lemma pricing constant-factor speedups of rho-type methods as asymptotically free, sharp against power-strength speedups.
\end{abstract}

\section{Introduction}

Let $N = pq$ be a semiprime with $p \ne q$ prime, and let $b$ be coprime to $N$. Essentially every classical factoring heuristic that is not a sieve is an attempt to detect the multiplicative structure of $(\mathbb{Z}/N)^{\times}$ through quantities computable from $N$ alone. The canonical such quantity is
\[
F(c) \;=\; \gcd\!\left(b^{c}-1,\; N\right),
\]
the \emph{cycle-index fingerprint} of $(N,b)$: computable in $O(\log c)$ modular multiplications plus one gcd, hence in time polynomial in $\log N$.

Our question is not whether $F$ can be used to factor --- it can, if one reaches the right index --- but exactly how much information $F$, or any object derived from it, carries about the factorization \emph{before} the order scale is reached. We answer this with exact identities.

Exactness matters because a genuine amplification channel exists. Knowing $N$ and $\sigma = p+q$ yields the factorization immediately, and lattice methods for small roots of modular polynomials amplify an approximation $\hat\sigma$ with $|\hat\sigma - \sigma| < N^{1/4}$ into a full factorization in polynomial time. Any \emph{source} of even weak information about $p+q$ computable from $N$ would therefore be a break. We prove that the fingerprint --- and its M\"obius spectrum, and its Burnside average, and every function of any of them --- is not such a source: below the order scale each is a constant function of the instance.

\paragraph{Notation.} $p \ne q$ are primes, $N = pq$, and $b \ge 1$ is coprime to $N$. We write $d_p = \ord_p(b)$, $d_q = \ord_q(b)$, $d^{*} = \min(d_p,d_q)$ (the \emph{order scale}), $n = \ord_N(b) = \lcmop(d_p,d_q)$, $\varphi$ for Euler's totient (so $\varphi(N) = (p-1)(q-1)$), $\mu$ for the M\"obius function, $\iv{P}$ for the Iverson bracket, and $v_p(m)$ for the exponent of $p$ in $m$.

\section{The objects of study}

\begin{definition}[Cycle-index fingerprint]
For integers $b, N$ and $c \ge 0$, set $F_{b,N}(c) = \gcd(b^{c}-1, N)$; subscripts are dropped when clear. Each value is computable in $\mathrm{poly}(\log N, \log c)$ time.
\end{definition}

\begin{definition}[Raw M\"obius spectrum]
For $d \ge 1$, $\displaystyle M_d = \sum_{c \mid d} \mu\!\left(\frac{d}{c}\right) F(c)$. This is $N$-computable.
\end{definition}

\begin{definition}[Valuation spectrum]
For a prime $p \mid N$ and $d \ge 1$, $\displaystyle M^{(p)}_d = \sum_{c \mid d} \mu\!\left(\frac{d}{c}\right) v_p\big(F(c)\big)$. This is not $N$-computable, but it is the cleanest diagnostic of spectral content.
\end{definition}

\begin{definition}[Observation window]
For $D \ge 1$ the \emph{truncated fingerprint} is $\mathcal{W}_D(p,q,b) = (F(1),\dots,F(D)) \in \mathbb{N}^{D}$ and the \emph{M\"obius window} is $\mathcal{M}_D(p,q,b) = (M_1,\dots,M_D) \in \mathbb{Z}^{D}$.
\end{definition}

\section{Structure of the fingerprint and the order seal}

\begin{lemma}[Order detection]\label{lem:order}
Let $p$ be prime and $b \ge 1$ with $p \nmid b$. Then $p \mid b^{c}-1 \iff d_p \mid c$.
\end{lemma}

\begin{proof}[Proof sketch]
Modulo $p$ the condition reads $b^{c} \equiv 1$ in the field $\mathbb{Z}/p$, and in any group $x^{c}=1$ holds exactly when the order of $x$ divides $c$.
\end{proof}

\begin{lemma}\label{lem:gcdprime}
For any $m$ and prime $p$, $\gcd(m,p) = p$ if $p \mid m$ and $1$ otherwise.
\end{lemma}

\begin{theorem}[Structure of the fingerprint]\label{thm:structure}
Let $N = pq$ with $p \ne q$ prime and $b \ge 1$. Then for every $c \ge 0$,
\[
F(c) \;=\; p^{\iv{d_p \mid c}}\, q^{\iv{d_q \mid c}} .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Coprimality of $p$ and $q$ gives $\gcd(m,pq) = \gcd(m,p)\gcd(m,q)$; apply Lemma~\ref{lem:gcdprime} to each factor and rewrite the divisibility conditions with Lemma~\ref{lem:order}.
\end{proof}

Thus $F$ is a two-tone multiplicative square wave: $1$ off $d_p\mathbb{Z}\cup d_q\mathbb{Z}$, $p$ on $d_p\mathbb{Z}\setminus d_q\mathbb{Z}$, $q$ on $d_q\mathbb{Z}\setminus d_p\mathbb{Z}$, and $N$ on $n\mathbb{Z}$.

\begin{lemma}\label{lem:ordpos}
If $p$ is prime and $p \nmid b$ then $d_p > 0$; indeed $d_p \mid p-1$.
\end{lemma}

\begin{theorem}[The order seal]\label{thm:seal}
For every $c$ with $0 < c < d^{*}$ we have $F(c) = 1$.
\end{theorem}

\begin{proof}[Proof sketch]
If $d_p \mid c$ with $c>0$ then $d_p \le c < d^{*} \le d_p$, absurd; likewise for $q$. Both indicators in Theorem~\ref{thm:structure} vanish.
\end{proof}

\begin{theorem}[Informative entry]\label{thm:entry}
$F(d^{*}) > 1$.
\end{theorem}

\begin{proof}[Proof sketch]
At $c = d^{*}$ the order attaining the minimum divides $c$, so the product contains a factor $\ge 2$.
\end{proof}

\begin{theorem}[The order scale splits $N$]\label{thm:splits}
Assume moreover $p\nmid b$, $q \nmid b$ and $d_p \ne d_q$. Then $1 < F(d^{*}) < N$ and $F(d^{*}) \mid N$; that is, $F(d^{*}) \in \{p,q\}$.
\end{theorem}

\begin{proof}[Proof sketch]
Say $d_p < d_q$, so $d^{*} = d_p$ and $d_q \nmid d_p$. Theorem~\ref{thm:structure} gives $F(d^{*}) = p$. The symmetric case is identical; divisibility is immediate.
\end{proof}

\begin{theorem}[Sharp threshold]
$d^{*}$ is the least element of $\{c>0 : F(c)>1\}$.
\end{theorem}

\begin{proof}[Proof sketch]
Membership is Theorem~\ref{thm:entry}; minimality is Theorem~\ref{thm:seal}.
\end{proof}

\begin{remark}
By Lemma~\ref{lem:ordpos}, $d_p \mid p-1$. For random $b$ the density of bases with $d_p \le B$ is at most $B^{2}/p$, so generically $d^{*}$ is comparable to $\min(p,q)\approx\sqrt{N}$; the exceptional small-$d^{*}$ instances are exactly the smooth-$(p-1)$ instances already exploited by Pollard's $p-1$ method. The square-root wall and the order seal are the same phenomenon.
\end{remark}

\section{The M\"obius spectrum}

\begin{lemma}[M\"obius detection]\label{lem:detect}
For positive integers $k, d$,
\[
\sum_{c \mid d} \mu\!\left(\frac{d}{c}\right)\iv{k \mid c} \;=\; \iv{k = d}.
\]
\end{lemma}

\begin{proof}[Proof sketch]
Substituting $c = d/j$ turns the sum into $\sum_{j\mid d}\mu(j)\iv{k \mid d/j}$. If $k \nmid d$ no term survives and $k \ne d$. If $d = ke$ then $k \mid d/j \iff j \mid e$, so the sum is $\sum_{j\mid e}\mu(j) = \iv{e=1}$, and $e=1 \iff k=d$.
\end{proof}

\begin{lemma}\label{lem:val}
$v_p\big(F(c)\big) = \iv{d_p \mid c}$.
\end{lemma}

\begin{theorem}[Valuation spectrum is an order delta]\label{thm:valspec}
For $d>0$ and $p \nmid b$, $M^{(p)}_d = \iv{d_p = d}$.
\end{theorem}

\begin{proof}[Proof sketch]
Substitute Lemma~\ref{lem:val} and apply Lemma~\ref{lem:detect} with $k = d_p > 0$.
\end{proof}

\begin{corollary}
If $0 < d < d^{*}$ then $M^{(p)}_d = M^{(q)}_d = 0$.
\end{corollary}

\begin{corollary}[Unit point mass over a window]
For any $D \ge 1$, $\sum_{d=1}^{D} M^{(p)}_d = \iv{d_p \le D}$: the entire content of the valuation spectrum over a window is the single bit ``the order scale has been reached''.
\end{corollary}

\begin{theorem}[The four-atom spectrum]\label{thm:fouratom}
Let $p \ne q$ be primes, $b \ge 1$ with $p \nmid b$, $q\nmid b$, and $d>0$. Then
\[
M_d \;=\; \iv{d=1} + (p-1)\iv{d_p=d} + (q-1)\iv{d_q=d} + (p-1)(q-1)\iv{n=d},
\]
where $n = \lcmop(d_p,d_q) = \ord_N(b)$.
\end{theorem}

\begin{proof}[Proof sketch]
Verify the pointwise inclusion--exclusion identity
\[
F(c) = 1 + (p-1)\iv{d_p \mid c} + (q-1)\iv{d_q \mid c} + (p-1)(q-1)\iv{n \mid c}
\]
by checking the four cases of the indicator pair, using $d_p \mid c \wedge d_q \mid c \iff n \mid c$. Then apply $\sum_{c\mid d}\mu(d/c)(\cdot)$ termwise and use Lemma~\ref{lem:detect} four times (with $k = 1, d_p, d_q, n$).
\end{proof}

\begin{corollary}[Instance-independence below the order scale]\label{cor:mobconst}
For $0 < d < d^{*}$ we have $M_d = \iv{d=1}$; hence $\mathcal{M}_D$ equals the universal vector $(1,0,\dots,0)$ for every instance with $D < d^{*}$.
\end{corollary}

The spectrum is thus four Dirac masses at $1, d_p, d_q, n$ with weights $1, p-1, q-1, \varphi(N)$. The weights are precisely the secrets --- recovering the mass at $n$ recovers $\varphi(N)$, hence the factorization --- but they are located at the order scale. M\"obius inversion is a genuine change of basis; it is not an information-relocating one.

\section{Zero information: the starvation theorem}

\subsection{The channel is real}

\begin{theorem}[Sum--product inversion]\label{thm:sumprod}
If $a+b = c+d$ and $ab = cd$ for positive integers, then $\{a,b\}=\{c,d\}$.
\end{theorem}

\begin{proof}[Proof sketch]
$(c-a)(c-b) = c^{2}-c(a+b)+ab = c^{2}-c(c+d)+cd = 0$, so $c \in \{a,b\}$ and the partner is forced by the sum.
\end{proof}

Hence $(N,\sigma)$ with $\sigma = p+q$ determines $\{p,q\}$ as the roots of $x^{2}-\sigma x + N$; lattice methods extend this to approximations accurate to $N^{1/4}$.

\begin{theorem}[Weighted inversion]\label{thm:weighted}
Let $A,B \ge 0$ with $pq = p'q' = N$ and $Ap+Bq = Ap'+Bq'$. Then $p = p'$ or $A\,p\,p' = B\,N$.
\end{theorem}

\begin{proof}[Proof sketch]
Substituting $q = N/p$, $q' = N/p'$ and clearing denominators yields $(p-p')\big(A(p+p') - (Ap+Bq)\big)=0$; the second factor rearranges to $App' = BN$ using $pq=N$.
\end{proof}

\begin{corollary}
If $A=0$ and $B>0$ the relation reads $Bq = Bq'$, so $q = q'$ and the hint determines the factorization outright.
\end{corollary}

\subsection{A finitary notion of zero information}

\begin{definition}[Counting independence]
Let $\Omega$ be a finite instance set, $T : \Omega \to \mathcal{T}$ a statistic, $S : \Omega \to \mathcal{S}$ a secret. Say $\ZeroInfo(\Omega,T,S)$ holds if for all $t,s$,
\[
\#\{\omega : T\omega = t,\ S\omega = s\}\cdot\#\Omega \;=\; \#\{\omega : T\omega = t\}\cdot\#\{\omega: S\omega = s\}.
\]
\end{definition}

Dividing by $\#\Omega^{2}$, this says the empirical joint law of $(T,S)$ under the uniform measure on $\Omega$ is a product measure: mutual information exactly zero, with no approximation.

\begin{lemma}[Constant statistics are uninformative]\label{lem:const}
If $T$ is constant on $\Omega$ then $\ZeroInfo(\Omega,T,S)$ for every $S$.
\end{lemma}

\begin{proof}[Proof sketch]
For the constant value the $T$-fibre is $\Omega$ and the joint fibre is the $S$-fibre; for any other value both fibres are empty.
\end{proof}

\begin{lemma}[Data processing]\label{lem:dpi}
If $\ZeroInfo(\Omega,T,S)$ and $g$ is any function on the range of $T$, then $\ZeroInfo(\Omega, g \circ T, S)$.
\end{lemma}

\begin{proof}[Proof sketch]
Partition each $(g\circ T)$-fibre into the $T$-fibres it contains; both sides of the defining identity are additive over this partition.
\end{proof}

\begin{lemma}[Non-vacuity]\label{lem:nonvac}
If $\omega_1 \ne \omega_2$ with $T\omega_1 \ne T\omega_2$ and $S\omega_1 \ne S\omega_2$, then $\ZeroInfo(\{\omega_1,\omega_2\},T,S)$ fails.
\end{lemma}

\begin{proof}[Proof sketch]
With $t = T\omega_1$, $s = S\omega_1$ all three fibres are $\{\omega_1\}$ and the identity would read $1\cdot 2 = 1 \cdot 1$.
\end{proof}

\subsection{Starvation}

Let $S_\ell(p,q,b) = (p+q)\bmod \ell$.

\begin{theorem}[Starvation of the truncated fingerprint]\label{thm:starved}
Let $D,\ell \ge 1$ and let $\Omega$ be any finite set of instances $(p,q,b)$ with $p \ne q$ prime, $b\ge 1$ and $D < \min(d_p,d_q)$ for each member. Then $\ZeroInfo(\Omega, \mathcal{W}_D, S_\ell)$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:seal}, $\mathcal{W}_D$ is the constant vector $(1,\dots,1)$ on $\Omega$; apply Lemma~\ref{lem:const}.
\end{proof}

\begin{theorem}[No post-processing helps]
Under the same hypotheses and for any $g$ on $\mathbb{N}^{D}$, $\ZeroInfo(\Omega, g\circ\mathcal{W}_D, S_\ell)$. In particular no hash, projection, estimator or learned predictor $\hat\sigma$ built from the window carries information about $(p+q)\bmod\ell$.
\end{theorem}

\begin{proof}[Proof sketch]
Lemma~\ref{lem:dpi} applied to Theorem~\ref{thm:starved}.
\end{proof}

\begin{theorem}[Starvation of the M\"obius window]
Under the same hypotheses, $\ZeroInfo(\Omega, \mathcal{M}_D, S_\ell)$.
\end{theorem}

\begin{proof}[Proof sketch]
By Corollary~\ref{cor:mobconst} the window is the constant vector $(1,0,\dots,0)$; apply Lemma~\ref{lem:const}.
\end{proof}

\begin{proposition}[Non-vacuity of the hypothesis]
For $(p,q,b) = (3,5,2)$ one has $d_3 = 2$, $d_5 = 4$, so a window of length $D=1$ is legitimate.
\end{proposition}

\begin{proposition}[Sharpness at the order scale]\label{prop:sharp}
On $\Omega = \{(3,5,2),(3,7,2)\}$ with $D = 4$ and $\ell = 3$, zero information fails: since $\ord_7(2) = 3$, the windows are $(1,3,1,15)$ and $(1,3,7,3)$, while $(3+5)\bmod 3 = 2 \ne 1 = (3+7)\bmod 3$. Apply Lemma~\ref{lem:nonvac}.
\end{proposition}

The dichotomy is total: below the order scale the window and every function of it are constants of the instance; at the order scale the window contains a proper factor of $N$ outright. There is no intermediate regime in which an attacker accumulates a statistical edge.

\section{Burnside's mirror: the orbit count}

The base $b$ determines a unit $u \in (\mathbb{Z}/N)^{\times}$, and $\langle u \rangle$ acts on $\mathbb{Z}/N$ by multiplication. Let $C$ be the number of orbits --- the homotopy cardinality of the action groupoid.

\begin{theorem}[The fingerprint is a fixed-point count]\label{thm:fix}
For $N = pq$ with $p \ne q$ prime and $b \ge 1$,
\[
\#\{x \in \mathbb{Z}/N : b^{k}x = x\} \;=\; \gcd(b^{k}-1,N) \;=\; F(k).
\]
\end{theorem}

\begin{proof}[Proof sketch]
By the Chinese Remainder Theorem $\mathbb{Z}/N \cong \mathbb{Z}/p\times\mathbb{Z}/q$ and the condition splits coordinatewise. In a field $cx=x$ has all of the field as solutions if $c = 1$ and only $x=0$ otherwise, so the count is $p^{\iv{b^{k}\equiv 1 \bmod p}} q^{\iv{b^{k}\equiv 1\bmod q}}$, which is $F(k)$ by Theorem~\ref{thm:structure}.
\end{proof}

\begin{lemma}
$\ord_N(b) = \lcmop(d_p,d_q) = n$.
\end{lemma}

\begin{lemma}\label{lem:mult}
If $d \mid n$, $d>0$, the number of $k \in \{0,\dots,n-1\}$ with $d \mid k$ is $n/d$.
\end{lemma}

\begin{theorem}[Period sum of the fingerprint]\label{thm:period}
For $p,q\ge 1$, $d_p,d_q>0$, $n = \lcmop(d_p,d_q)$,
\[
\sum_{k=0}^{n-1} p^{\iv{d_p\mid k}} q^{\iv{d_q \mid k}} \;=\; n + (p-1)\frac{n}{d_p} + (q-1)\frac{n}{d_q} + (p-1)(q-1).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Use the inclusion--exclusion expansion of Theorem~\ref{thm:fouratom} and sum termwise over a period with Lemma~\ref{lem:mult}; the last term contributes exactly one multiple.
\end{proof}

\begin{theorem}[Orbit-count identity]\label{thm:orbit}
With notation as above,
\[
C\cdot n \;=\; n + (p-1)\frac{n}{d_p} + (q-1)\frac{n}{d_q} + (p-1)(q-1),
\qquad\text{i.e.}\qquad
C = 1 + \frac{p-1}{d_p} + \frac{q-1}{d_q} + \frac{\varphi(N)}{n}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Burnside's lemma gives $C\cdot \#\langle u\rangle = \sum_{g\in\langle u\rangle}\#\Fix(g)$. The group has order $n$ and its elements are $u^{k}$, $0\le k<n$; by Theorem~\ref{thm:fix} the $k$-th fixed-point count is $F(k)$. Evaluate with Theorem~\ref{thm:period}.
\end{proof}

\begin{theorem}[Balanced case: no leak]\label{thm:balanced}
If $d_p = d_q = d$ then $C\cdot d = d + N - 1$. Hence $C$ is a function of $N$ and $\ord_N(b) = d$ alone and is independent of how $N$ splits.
\end{theorem}

\begin{proof}[Proof sketch]
Then $n = d$ and $n/d_p = n/d_q = 1$, so Theorem~\ref{thm:orbit} reads $Cd = d + (p-1)+(q-1)+(p-1)(q-1) = d + pq - 1$.
\end{proof}

\begin{theorem}[Affine-hint dichotomy]\label{thm:affine}
Substituting $(p-1)(q-1) = N - p - q + 1$ into Theorem~\ref{thm:orbit} and rearranging gives
\[
\left(\frac{n}{d_p}-1\right)p + \left(\frac{n}{d_q}-1\right)q \;=\; Cn - n + \frac{n}{d_p} + \frac{n}{d_q} - N - 1 .
\]
By Theorem~\ref{thm:weighted}, knowledge of the right-hand side together with $N$ pins the factorization to at most two candidates, unless both coefficients vanish --- which happens exactly in the balanced case $d_p = d_q$ of Theorem~\ref{thm:balanced}.
\end{theorem}

Thus the orbit count is either essentially equivalent to the factorization, or a function of $(N,\ord_N b)$ carrying no information about the splitting. Since by Theorem~\ref{thm:fix} it is a $\mathbb{Z}$-linear functional of the fingerprint over one period, Burnside's lemma re-sums exactly the data already shown to be sealed at the order scale: topological and categorical re-encodings give new descriptions, not new computation.

\section{Pricing constant-factor improvements}

For rho-type methods one may schedule early aborts using the Dickman function $\rho$, which governs the density of smooth integers; measurements give a mean speedup of about $1.95$.

\begin{theorem}[Exponent invariance]\label{thm:expinv}
Let $T,T' : \mathbb{N}\to\mathbb{R}$ and $C \ge 1$ satisfy $T'(n)>1$, $T'(n)\le T(n)\le C\,T'(n)$, and $T'(n)\to\infty$. Then $\log T(n)/\log T'(n) \to 1$.
\end{theorem}

\begin{proof}[Proof sketch]
The ratio is $\ge 1$ since $\log T \ge \log T' > 0$, and $\le 1 + \log C/\log T'(n)$ since $\log T \le \log C + \log T'$; the upper bound tends to $1$. Squeeze.
\end{proof}

\begin{corollary}
A uniform speedup $T = C\,T'$, in particular the measured $C \approx 1.95$, leaves the running-time exponent equal to $1$: asymptotically free.
\end{corollary}

\begin{theorem}[Sharpness]
If $T = (T')^{\theta}$ with $T' > 1$, then $\log T/\log T' \to \theta$.
\end{theorem}

Constant factors never move the exponent; power-strength improvements always do.

\section{Algorithms}

\paragraph{Fingerprint evaluation.} Given $N, b, c$, compute $r = b^{c}\bmod N$ by square-and-multiply and return $\gcd(r-1 \bmod N, N)$: $O(\log c)$ multiplications plus one gcd. Evaluating $F$ at a single large index is cheap; \emph{reaching} an index at the order scale is not.

\paragraph{Raw M\"obius coefficient.} Given $N,b,d$, enumerate the divisors $c \mid d$ and accumulate $\mu(d/c)F(c)$: $\tau(d)$ fingerprint evaluations. By Corollary~\ref{cor:mobconst} the output is $\iv{d=1}$ for all $d<d^{*}$, so the procedure is an order detector and nothing more.

\paragraph{Window scan and order-scale certificate.} Given $N,b,D$, scan $c = 1,\dots,D$ computing $F(c)$ incrementally (one multiplication per step) and return the first $F(c)\notin\{1,N\}$; if none occurs, return the certificate ``$\min(d_p,d_q)>D$'', whose correctness is Theorem~\ref{thm:seal}. Gcds may be batched into $O(D/k)$ by accumulating products of $k$ consecutive values of $b^{c}-1$ modulo $N$.

\paragraph{Orbit count.} Given $p,q,b$, compute $d_p,d_q,n$ and return $1 + (p-1)/d_p + (q-1)/d_q + (p-1)(q-1)/n$. The required input is the factorization --- which is the content of Theorem~\ref{thm:affine}.

\section{Applications and discussion}

A failed window scan is a cheap, verifiable certificate that both local orders exceed $D$, useful for base validation without knowing the factorization. The four-atom spectrum identifies weak instances precisely as those with a small local order, i.e.\ with smooth $p-1$, recovering from the spectral side the classical recommendation to use safe primes $p = 2p'+1$. The proof pattern of Section 5 --- show the observable is \emph{literally constant}, then invoke data processing --- is reusable and far stronger than a statistical estimate; any proposed statistic on the window inherits the closure with no new analysis. Finally, the results locate the quantum exception exactly: a period-finding subroutine determines $n$ directly and, by Theorem~\ref{thm:splits}, reaching the order scale is factoring; the advantage lies in reaching the scale, not in extracting more from sub-order-scale data, where there is nothing to extract.

Four apparently independent approaches collapse onto the same invariant: reading the fingerprint, M\"obius-inverting it, measuring its correlation with $p+q$, and Burnside-averaging it. The reason is visible in Theorems~\ref{thm:structure} and \ref{thm:fix}: everything here is a linear functional of the indicator pair $(\iv{d_p\mid c}, \iv{d_q \mid c})$. Any transform linear in the fingerprint values --- M\"obius inversion, Burnside averaging, Dirichlet convolution with any kernel, Fourier analysis over a period --- can only redistribute mass among the atoms; it cannot create an atom below $d^{*}$, because the underlying sequence is constant there.

\paragraph{Limitations.} The zero-information results assume both orders exceed the window; families containing small-order instances are exactly those classical methods already exploit, and there the results correctly fail (Proposition~\ref{prop:sharp}). The counting notion of independence is exact but finitary. And the analysis concerns uniform, hint-free access to this particular observable; sieve-based methods live in a different world and are unaffected.

\section{Future directions}

\begin{conjecture}[Spectral rigidity]
For $N$ with $k$ distinct prime factors and generic $b$, the raw spectrum has exactly $2^{k}$ atoms, indexed by subsets $S$ of the prime divisors, with mass $\prod_{p\in S}(p-1)$ located at $\lcmop_{p\in S}\ord_p b$. Consequently the raw spectrum has at most four nonzero coefficients for every base if and only if $N$ is a prime power or a semiprime. An $N$-computable count of spectral atoms would therefore be a primality-structure oracle.
\end{conjecture}

\begin{conjecture}[Order-scale barrier as an information dichotomy]
For every $D$ and every finite instance family with $d^{*}>D$, any statistic computable from $(N,b,F(1),\dots,F(D))$ has zero information about $(p+q)\bmod\ell$; conversely, for every family with $d^{*}\le D$ there exist $\ell$ and a statistic with strictly positive information. The missing step is to prove the window is a sufficient statistic for $(N,b)$ below the order scale.
\end{conjecture}

\begin{conjecture}[Burnside seal, general form]
For any finite abelian group $G$ and $g \in G$ acting on a $G$-set built functorially from $\mathbb{Z}/N$, the orbit count is a $\mathbb{Z}$-linear functional of the fixed-point sequence $k \mapsto \#\Fix(g^{k})$, and every such functional is computable from $(N,\ord_N b)$ alone precisely when the local orders coincide.
\end{conjecture}

Beyond these, two further questions: whether a \emph{nonlinear} functional of the fingerprint can escape the structural obstruction (it cannot escape constancy below $d^{*}$, so the real question is whether a cheap observable exists that is not a function of any sub-order-scale window); and how far the certified order lower bounds of Section 8 can be pushed economically in practice.

\section{Conclusion}

The cycle-index fingerprint of a semiprime is a rich, freely computable object with a genuinely interesting spectral theory: its M\"obius transform is a sum of four Dirac masses with weights $1$, $p-1$, $q-1$ and $\varphi(N)$, and its Burnside average is the orbit count of the natural cyclic action on $\mathbb{Z}/N$. Neither structure relocates any information. Below the order scale $d^{*} = \min(\ord_p b, \ord_q b)$ the fingerprint, its spectrum, and every function of either are literally constant across all instances; at the order scale the fingerprint hands over a factor of $N$. The classical, uniform, hint-free surface around this observable is closed, and the seal sits exactly at the order scale --- the square-root wall in disguise.

